-- Eventos y asistentes ficticios: carga directa, no solicita confirmaciones SMTP.
begin;
lock table public.eventos,public.inscripciones in share row exclusive mode;
create temporary table carga_eventos(codigo text,sucursal text,mes integer,fecha date,confirmados integer,tema text) on commit drop;

do $$ begin
 if (select count(*) from carga_eventos c join public.sucursales s on s.codigo=c.sucursal)<>11 then raise exception 'Faltan sucursales para los once eventos'; end if;
 if exists(select 1 from carga_eventos c join public.sucursales s on s.codigo=c.sucursal where not extract(isodow from c.fecha)::integer::text=any(string_to_array(s.dias_entrega,',')) or time '10:00'<s.apertura or time '12:00'>s.cierre) then raise exception 'Hay un evento fuera del horario de atencion'; end if;
end $$;

select s.id_sucursal,c.codigo||' · '||c.tema,
 'Actividad ficticia de referencia: '||c.tema||'. Horario de Guatemala. Los participantes confirmados de esta carga son datos de prueba; la confirmacion no acredita asistencia presencial.',
 (c.fecha+time '10:00') at time zone 'America/Guatemala',(c.fecha+time '12:00') at time zone 'America/Guatemala',true,30,24
from carga_eventos c join public.sucursales s on s.codigo=c.sucursal
where not exists(select 1 from public.eventos e where e.titulo=c.codigo||' · '||c.tema);

create temporary table carga_asistentes(evento text,nombre text,email text,token_hash text) on commit drop;

select e.id_evento,a.nombre,a.email,null,'CONFIRMADA',a.token_hash,e.inicio-interval '7 days',e.inicio-interval '7 days'+interval '2 hours'
from carga_asistentes a join carga_eventos c on c.codigo=a.evento
join public.eventos e on e.titulo=c.codigo||' · '||c.tema
on conflict(id_evento,email) do nothing;

do $$ begin
 if (select count(*) from carga_eventos c join public.eventos e on e.titulo=c.codigo||' · '||c.tema)<>11 then raise exception 'No se crearon once eventos'; end if;
 if exists(select 1 from carga_eventos c join public.eventos e on e.titulo=c.codigo||' · '||c.tema where (select count(*) from public.inscripciones i where i.id_evento=e.id_evento and i.estado='CONFIRMADA')<>c.confirmados) then raise exception 'El total de confirmados no coincide con la carga'; end if;
end $$;
commit;
